import{_ as a,C as r,o as n,c as i,E as o,a2 as l}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"迁移安全不能只看输出正确，还要证明 Conformance 真正在每个后端执行","description":"","frontmatter":{"title":"迁移安全不能只看输出正确，还要证明 Conformance 真正在每个后端执行","date":"2026-08-09","column":"open-source-engineering","category":"daily","summary":"持久状态迁移可能在结果仍然正确时破坏关键机制，例如把有界增量回放退化成每次从根历史重放。治理迁移需要读端兼容所有受支持的历史表示，并把跨后端 Conformance 的实际执行情况作为 CI 事实，而不是把测试文件存在等同于覆盖。","item_id":"Q-20260809-03","source_research_object":"research/analysis/Q-20260809-03-executed-conformance-migration-safety.md","source_reading_result":"research/reading/Q-20260809-03-checkpoint-conformance-migration.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-09-executed-conformance-migration-safety-cover-v2.jpg"},"headers":[],"relativePath":"zh/engineering/2026-08-09-executed-conformance-migration-safety.md","filePath":"zh/engineering/2026-08-09-executed-conformance-migration-safety.md","lastUpdated":1787407830000}'),c={name:"zh/engineering/2026-08-09-executed-conformance-migration-safety.md"};function d(s,e,h,g,m,u){const t=r("ArticleCover");return n(),i("div",null,[o(t,{image:"/assets/covers/daily-2026-08-09-executed-conformance-migration-safety-cover-v2.jpg",kicker:"开源工程 · 每日研究",title:"迁移安全不能只看输出正确，还要证明 Conformance 真正在每个后端执行",summary:"持久状态迁移可能在结果仍然正确时破坏关键机制，例如把有界增量回放退化成每次从根历史重放。治理迁移需要读端兼容所有受支持的历史表示，并把跨后端 Conformance 的实际执行情况作为 CI 事实，而不是把测试文件存在等同于覆盖。",version:"Q-20260809-03",status:"Daily Runtime V5 · 2026-08-09",languageHref:"/en/engineering/2026-08-09-executed-conformance-migration-safety",languageLabel:"English"}),e[0]||(e[0]=l(' # 迁移安全不能只看输出正确，还要证明 Conformance 真正在每个后端执行 <p>持久化系统最隐蔽的迁移缺陷，不一定表现为错误结果。一个 Reader 即使遗漏了历史状态中的有效 Seed，也可能通过从根节点重放全部写入，最终重建出同样的值。用户看到的输出正确，但原本承诺的有界回放、延迟和存储访问机制已经失效。</p><h2 id="核心判断" tabindex="-1">核心判断 <a class="header-anchor" href="#核心判断" aria-label="Permalink to &quot;核心判断&quot;">​</a></h2><p><strong>迁移安全是 Reader 对历史表示的兼容契约，也是 Conformance 在真实后端上的执行事实。</strong></p><p>只修新 Writer 不能修复已经落盘的旧数据；只检查测试文件存在，也不能证明相关 Backend 真正运行过测试。若一个架构机制承诺有界回放或固定查询复杂度，这些性能性质本身就是可验证的正确性条件。</p><p>本文唯一分析输入是 <code>Q-20260809-03</code> Research Object。Production 未对数据库实现进行新的独立 Benchmark。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>本文基于 <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-03-executed-conformance-migration-safety.md" target="_blank" rel="noreferrer">Research Object — Executed Conformance for Migration Safety</a>。证据追溯入口是 <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-03-checkpoint-conformance-migration.md" target="_blank" rel="noreferrer">Reading Result — Checkpoint Conformance and Persisted-State Migration</a>。</p><p>Reading Result 记录的具体缺陷发生在持久化 Delta History Seed 查找：历史值可能保存在内联 <code>channel_values</code>，也可能保存在 <code>checkpoint_blobs</code>。旧逻辑依赖一种 Marker，导致迁移后的 Plain Value Seed 不可见。</p><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>Seed 未被识别时，系统仍可以从空状态开始回放所有历史写入。对于加法型 Reducer，最终列表可能与正确结果一致，因此普通输出断言无法发现机制退化。</p><p>Research Object 保留了以下实现事实：</p><ul><li>修复后的 Reader 同时检查 Blob 和 Inline 两种存储位置；</li><li>当 Blob 存在时优先解析 Blob，否则使用 Inline Value；</li><li>Writer-only Marker 修复不会覆盖已经存在的历史 Checkpoint；</li><li><code>None</code> 在该层无法与“没有值”可靠区分，因此不被当作 Seed；</li><li>直接回归测试覆盖 Plain Value、Snapshot、Version Bump 和 Inline Primitive；</li><li>所选实现报告 Postgres Conformance 从 6/8 提升到 8/8；</li><li>通用 Conformance 对部分 Backend 可能因为依赖缺失而静默 Skip。</li></ul><h2 id="安全层次比较" tabindex="-1">安全层次比较 <a class="header-anchor" href="#安全层次比较" aria-label="Permalink to &quot;安全层次比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查层</th><th style="text-align:right;">能发现输出错误</th><th style="text-align:right;">能发现历史表示不兼容</th><th style="text-align:right;">能发现回放复杂度退化</th><th style="text-align:right;">能证明每个后端有覆盖</th></tr></thead><tbody><tr><td>结果值单元测试</td><td style="text-align:right;">是</td><td style="text-align:right;">不一定</td><td style="text-align:right;">否</td><td style="text-align:right;">否</td></tr><tr><td>Backend 本地回归测试</td><td style="text-align:right;">是</td><td style="text-align:right;">针对已知缺陷</td><td style="text-align:right;">可以</td><td style="text-align:right;">只覆盖单个后端</td></tr><tr><td>共享 Conformance 文件存在</td><td style="text-align:right;">理论上</td><td style="text-align:right;">理论上</td><td style="text-align:right;">取决于断言</td><td style="text-align:right;">否，可能被 Skip</td></tr><tr><td>每个 Backend 实际执行 Conformance</td><td style="text-align:right;">是</td><td style="text-align:right;">是</td><td style="text-align:right;">可显式编码</td><td style="text-align:right;">是</td></tr></tbody></table><p>表格是 Research Center 基于 Research Object 的测试治理综合。</p><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>迁移兼容的责任首先在 Reader。新版本 Writer 只能决定未来数据如何保存，无法改变已经存在的 Plain Value、Blob、Marker 或旧 Schema。只给新写入补 Marker，等于让新数据健康、旧数据继续退化。</p><p>第二个问题是测试的“存在”和“执行”不能混同。仓库里有一个 Conformance 文件，不代表 CI 安装了依赖、构造了目标 Backend 并真正执行了全部 Case。<code>importorskip</code> 对可选功能很有用，但如果该 Backend 已被列为受治理实现，静默 Skip 就应该被视为缺失覆盖，而不是绿色通过。</p><p>第三个问题是性能不总是非功能指标。Delta Channel 的核心设计就是避免每次从根历史回放；一旦读取次数随线程长度线性增长，即使最后值正确，架构契约也已经被破坏。因此 Replay Count、Query Count 或最大扫描页数需要进入测试断言。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对 CodeFlowMu 和 Research Runtime，Schema 演进应保留一组历史 Fixture：扁平 Result、结构化 Narrative、旧 Metric Name、字符串 Evidence/Artifact 等。每次 Validator 或 Markdown Projection 修改都应在这些 Fixture 上执行，而不是只验证当前 Writer 产生的新格式。</p><p>对数字员工的 WorkOrder 存储，迁移记录还应说明 Reader 支持的历史表示范围、修复扫描边界和最坏回放成本。运营者需要知道“值可读”与“读取机制符合设计”是两个不同结论。</p><h2 id="边界与不确定性" tabindex="-1">边界与不确定性 <a class="header-anchor" href="#边界与不确定性" aria-label="Permalink to &quot;边界与不确定性&quot;">​</a></h2><p>所选具体缺陷是 Postgres 路径问题；Reading Result 明确指出 SQLite 的存储方式不同，并不受同一 Bug 影响。文中的延迟与回放数字来自维护者测试，不是 Research Center 的独立生产 Benchmark。</p><p>因此，本文不主张所有 Backend 必须共享完全相同的内部实现，而主张它们必须共享可执行的外部语义和关键不变量。</p><h2 id="未来工作" tabindex="-1">未来工作 <a class="header-anchor" href="#未来工作" aria-label="Permalink to &quot;未来工作&quot;">​</a></h2><p>下一步应确定哪些 Conformance 属于“不可 Skip”的发布门禁；如何让 CI 明确报告 Not Run 与 Pass；如何把 Replay/Query 复杂度编码成跨后端不变量；以及 Schema Version 如何帮助 Reader 选择历史解析路径。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>配图展示 Inline 与 Blob 两种历史表示进入 Migration-aware Reader，再由实际执行的 Backend Conformance 验证。底部强调“输出正确”并不等于“迁移不变量安全”。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-03-executed-conformance-migration-safety.md" target="_blank" rel="noreferrer">Research Object — Executed Conformance for Migration Safety</a>：本文唯一分析输入。</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-03-checkpoint-conformance-migration.md" target="_blank" rel="noreferrer">Reading Result — Checkpoint Conformance and Persisted-State Migration</a>：实现事实、测试结果、限制与未决问题的追溯入口。</li></ol>',32))])}const b=a(c,[["render",d]]);export{f as __pageData,b as default};
